raw:
{
  "spells": [
    {
      "id": "spell_light_04",
      "theory": "反照印让魔力停留在标记的浅层纹路里，纹路不发光，只把来自指定方向的微弱光亮折回原处。标记可以是石片、木牌或布条，表面需有能让魔力附着的粗糙度。折回的光强弱取决于来光，标记自身不产生新光，因此黑暗中无光可折时它毫无作用。",
      "casting": "用拇指按住标记中心，另一手食指沿边缘画半弧指向来光方向，同时缓缓注入魔力，直到纹路微微发涩。",
      "failure": "边缘弧线画歪时，标记只闪出零散亮点，很快暗淡。魔力若送得太急，纹路会发热卷曲，标记表面留下焦痕，反光方向也变得散乱难辨。",
      "counters": [
        "转动标记或移动自身位置，使来光方向不再对准纹路。",
        "用不透明布片盖住标记，折回的光便被完全阻断。"
      ],
      "socialConsequences": "河谷乡民常用它标记渡口浅滩，使夜行船工看清岸边石堆。渡船人欢迎这种指引，偷采河砂的人却讨厌标记暴露浅滩位置，可能趁夜刮花纹路。乡约见证的民事承诺中，若有人擅自移走标记，会被要求按原样补回并赔偿船工绕行的损失。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把半弧画偏，折回的光斑歪斜，需反复调整标记朝向。",
        "熟练后能稳定对准来光方向，折回的光斑落在预期位置上。",
        "更熟练者可让标记在轻微晃动时仍保持大致方向，减少船工误判。",
        "极高熟练度下纹路几乎不发热，折回光斑边界清晰，仍只折回指定方向的光。"
      ]
    },
    {
      "id": "spell_light_05",
      "theory": "眩点术把魔力压入指定位置的一点，使其在瞬间释放为强烈亮斑，强光只持续一眨眼的工夫，随后魔力散尽。亮斑本身不发热，也不附着在物体上，而是在施术者选定的空处爆开。闭眼的人不会受到干扰，因为强光需要进入眼睛才能影响视线。",
      "casting": "五指并拢指向目标空处，拇指扣住中指，注入魔力时中指弹开，掌心朝外一推，亮斑即在指尖前方炸开。",
      "failure": "魔力送入过慢时，亮斑变成一团昏暗的黄雾，只让人看到模糊色块。若手指未及时弹开，亮斑可能在掌前偏斜处炸开，反而晃到施术者自己的眼角。",
      "counters": [
        "在亮斑炸开前闭眼或侧头，强光便无法进入眼睛。",
        "举起不透明盾牌或厚布挡在面前，亮斑会被遮住。"
      ],
      "socialConsequences": "港务规定追究航运事故与货损，因此码头夜间卸货时，若有人朝船工方向施放眩点术导致货物落水，港务会按货损追究责任。竞争者常指责对方在集市用此术干扰叫卖，但闭眼者不受影响，所以老练的商贩会养成侧头避光的习惯。城市公会许可的庆典中，此术只许朝空处施放，不得瞄准具体人的面部。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把亮斑炸在指尖太近处，自己也会被余光晃到，需要多加练习。",
        "熟练后能稳定在目标空处炸开，亮斑持续一瞬便熄灭，不伤及旁人。",
        "更熟练者可在移动中大致瞄准，亮斑仍只在一瞬干扰视线，闭眼者不受影响。",
        "极高熟练度下亮斑边界清晰、位置准确，仍不产生热量，也无法穿透遮挡。"
      ]
    },
    {
      "id": "spell_light_06",
      "theory": "辨色谱将魔力铺在样品表面，使矿物或染料中不同色泽的微粒对魔力产生细微阻力差异，施术者由此看出色泽的分层。魔力只停留在样品表层，不改变样品本身，也不会凭空造出颜色。样品必须提供，且需有可观察的平整面，粉末或液体则需盛在浅碟中。",
      "casting": "将样品放在掌心或浅碟上，另一手食指在样品上方缓慢画圈，同时送入魔力，直到指尖感到细微的涩滞变化。",
      "failure": "若样品表面太粗糙或魔力送得过猛，色泽会混成一片灰暗，看不出分层。样品含油污时，魔力可能滑开不附着，指尖只感到空转，浪费掉的魔力无法收回。",
      "counters": [
        "用细布擦去样品表面油污，使魔力无法均匀附着。",
        "掺入大量同色粉末，使色泽分层被均匀混合物掩盖。"
      ],
      "socialConsequences": "琥珀海岸的染料商依赖此术检验进货，港务处理货损纠纷时也会请人辨色以确认染料是否被海水浸坏。矿山主担心此术让买家看穿矿石品位，压低收购价，因此常要求先付定金再验。城市公会许可的珠宝交易中，验色者须经同意才能触碰他人货品，擅自将魔力探入他人私有样品会被视为侵犯隐私。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把色泽看成一片模糊，只能分辨出差异明显的两种颜色。",
        "熟练后能稳定看出矿物与染料的色泽分层，仍依赖样品表面平整。",
        "更熟练者可快速判断染料是否被海水浸坏，减少港务纠纷中的误判。",
        "极高熟练度下能分辨极细微的色泽差异，但魔力仍只停留在样品表层，不改变样品。"
      ]
    }
  ]
}
